    correction: [{"quoi":"شرط القسمة على 4","math":"العدد يقبل القسمة على 4 إذا كان العدد المكوّن من رقمي عشراته و آحاده يقبل القسمة على 4"},{"quoi":"رقم الآحاد معلوم","math":"رقم آحاد العدد 360a5 هو 5"},{"quoi":"الشرط يتعلّق بـ a","math":"الشرط يتعلّق برقمي العشرات و الآحاد، أي بالعدد a5 الذي يتغيّر مع a"},{"quoi":"مثال مضادّ","math":"من أجل <span dir=\"ltr\" class=\"expr\">a = 3</span> نجد العدد 36035 الذي لا يقبل القسمة على 4"},{"quoi":"الجواب","math":"خطأ"}],
