    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 12 لا يفوق 9403 هو <span dir=\"ltr\" class=\"expr\">12 × 783</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">12 × 783 = 9396</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">9403 - 9396 = 7</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">7 &lt; 12</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">9403 = 12 × 783 + 7</span>"},{"quoi":"الجواب","math":"صواب"}],
