    correction: [{"quoi":"شرط الباقي","math":"الباقي في القسمة على 5 يجب أن يكون أصغر تماما من 5"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">9 &gt; 5</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 9 لا يمكن أن يكون باقي قسمة على 5"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">9 = 5 × 1 + 4</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">10y + 9 = 5(2y + 1) + 4</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 4 لأنّ 4 < 5"},{"quoi":"الجواب","math":"خطأ"}],
