    correction: [{"quoi":"نفكّك العبارة الأولى","math":"<span dir=\"ltr\" class=\"expr\">6n + 9 = 3(2n + 3)</span>"},{"quoi":"نفكّك العبارة الثانية","math":"<span dir=\"ltr\" class=\"expr\">6n + 3 = 3(2n + 1)</span>"},{"quoi":"نستنتج قاسما مشتركا","math":"العدد 3 يقسم العبارتين مهما يكن n"},{"quoi":"نقارن بالتعريف","math":"عددان أوليان فيما بينهما ق.م.أ لهما يساوي 1، و هنا ق.م.أ يقبل القسمة على 3"},{"quoi":"الجواب","math":"خطأ"}],
