    correction: [{"quoi":"القاعدة","math":"نكتب البسط بدلالة المقام لنُظهر جزءا صحيحا و باقيا"},{"quoi":"ننشر للتحقّق","math":"<span dir=\"ltr\" class=\"expr\">4(n + 7) = 4n + 28</span>"},{"quoi":"نكتب البسط بدلالة المقام","math":"<span dir=\"ltr\" class=\"expr\">4n + 56 = 4(n + 7) + 28</span>"},{"quoi":"نعوّض في M","math":"<span dir=\"ltr\" class=\"expr\">(4n + 56)/(n + 7) = (4(n + 7) + 28)/(n + 7)</span>"},{"quoi":"نفصل الكسرين","math":"<span dir=\"ltr\" class=\"expr\">(4(n + 7) + 28)/(n + 7) = 4(n + 7)/(n + 7) + 28/(n + 7)</span>"},{"quoi":"نختصر الكسر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">4(n + 7)/(n + 7) = 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 4 + 28/(n + 7)</span>"}],
